#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_bf16.h>

#define ROWS_PER_BLOCK 16

template<int RPB>
__global__ __launch_bounds__(RPB*32, 2)
void gemv_kernel(const __nv_bfloat16* __restrict__ x,
                 const __nv_bfloat16* __restrict__ W,
                 __nv_bfloat16* __restrict__ y,
                 int N, int K) {
    int tid = threadIdx.x;
    int lane = tid & 31;
    int wr = tid >> 5;
    int row = blockIdx.x * RPB + wr;
    if (row >= N) return;

    const __nv_bfloat16* __restrict__ wrow = W + (long long)row * K;
    float sum = 0.0f;

    // Common LLM/GEMV dimensions are even; using bf16x2 halves loop-control
    // overhead and gives 32-bit coalesced loads while still accumulating in fp32.
    if ((K & 1) == 0) {
        int K2 = K >> 1;
        const __nv_bfloat162* __restrict__ x2 = reinterpret_cast<const __nv_bfloat162*>(x);
        const __nv_bfloat162* __restrict__ w2 = reinterpret_cast<const __nv_bfloat162*>(wrow);
        int j = lane;
        #pragma unroll 4
        for (; j + 96 < K2; j += 128) {
            float2 xf0 = __bfloat1622float2(x2[j]);     float2 wf0 = __bfloat1622float2(w2[j]);
            float2 xf1 = __bfloat1622float2(x2[j+32]);  float2 wf1 = __bfloat1622float2(w2[j+32]);
            float2 xf2 = __bfloat1622float2(x2[j+64]);  float2 wf2 = __bfloat1622float2(w2[j+64]);
            float2 xf3 = __bfloat1622float2(x2[j+96]);  float2 wf3 = __bfloat1622float2(w2[j+96]);
            sum = fmaf(xf0.x, wf0.x, sum); sum = fmaf(xf0.y, wf0.y, sum);
            sum = fmaf(xf1.x, wf1.x, sum); sum = fmaf(xf1.y, wf1.y, sum);
            sum = fmaf(xf2.x, wf2.x, sum); sum = fmaf(xf2.y, wf2.y, sum);
            sum = fmaf(xf3.x, wf3.x, sum); sum = fmaf(xf3.y, wf3.y, sum);
        }
        for (; j < K2; j += 32) {
            float2 xf = __bfloat1622float2(x2[j]);
            float2 wf = __bfloat1622float2(w2[j]);
            sum = fmaf(xf.x, wf.x, sum);
            sum = fmaf(xf.y, wf.y, sum);
        }
    } else {
        int k = lane;
        #pragma unroll 4
        for (; k + 96 < K; k += 128) {
            sum = fmaf(__bfloat162float(x[k]),    __bfloat162float(wrow[k]),    sum);
            sum = fmaf(__bfloat162float(x[k+32]), __bfloat162float(wrow[k+32]), sum);
            sum = fmaf(__bfloat162float(x[k+64]), __bfloat162float(wrow[k+64]), sum);
            sum = fmaf(__bfloat162float(x[k+96]), __bfloat162float(wrow[k+96]), sum);
        }
        for (; k < K; k += 32) {
            sum = fmaf(__bfloat162float(x[k]), __bfloat162float(wrow[k]), sum);
        }
    }

    sum += __shfl_down_sync(0xffffffff, sum, 16);
    sum += __shfl_down_sync(0xffffffff, sum, 8);
    sum += __shfl_down_sync(0xffffffff, sum, 4);
    sum += __shfl_down_sync(0xffffffff, sum, 2);
    sum += __shfl_down_sync(0xffffffff, sum, 1);

    if (lane == 0) y[row] = __float2bfloat16_rn(sum);
}

torch::Tensor gemv_bf16_cuda(torch::Tensor x, torch::Tensor W) {
    const int64_t N64 = W.size(0);
    const int64_t K64 = W.size(1);
    auto y = torch::empty({N64}, x.options());
